// Extract the innertube API key from the page
const html = $input.first().json.data;
const videoId = $('Extract YouTube Video ID').first().json.videoId;

// Extract API key with improved regex
const apiKeyMatch = html.match(/"INNERTUBE_API_KEY":"\s*([^"]+)"/);
if (!apiKeyMatch) {
    throw new Error('Could not find YouTube API key in page. Video may be restricted or unavailable.');
}
const apiKey = apiKeyMatch[1];

// IMPORTANT: Use ANDROID client for better caption availability
const context = {
    client: {
        clientName: "ANDROID",
        clientVersion: "20.10.38",
        androidSdkVersion: 30,
        userAgent: "com.google.android.youtube/20.10.38 (Linux; U; Android 11) gzip",
        hl: "en",
        timeZone: "UTC",
        utcOffsetMinutes: 0
    }
};

return [{
    json: {
        videoId: videoId,
        apiKey: apiKey,
        context: context,
        preferredLanguage: "en"
    }
}];

const item = $input.first();
const youtubeUrl = item.json['YouTube Video URL'] || '';

let videoId = null;

// Try each pattern until we find a match
const patterns = [
  /[?&]v=([a-zA-Z0-9_-]{11})/,   // youtube.com/watch?v=
  /youtu\.be\/([a-zA-Z0-9_-]{11})/, // youtu.be/
  /embed\/([a-zA-Z0-9_-]{11})/,  // youtube.com/embed/
  /shorts\/([a-zA-Z0-9_-]{11})/, // youtube.com/shorts/
  /live\/([a-zA-Z0-9_-]{11})/,   // youtube.com/live/
];

for (const pattern of patterns) {
  const match = youtubeUrl.match(pattern);
  if (match) {
    videoId = match[1];
    break;
  }
}

// Check if it's already just the video ID
if (!videoId && /^[a-zA-Z0-9_-]{11}$/.test(youtubeUrl.trim())) {
  videoId = youtubeUrl.trim();
}

item.json.videoId = videoId;
item.json.standardUrl = videoId
  ? `https://www.youtube.com/watch?v=${videoId}`
  : null;

return $input.all();

// Enhanced caption extraction with better error handling
const playerData = $json;
const preferredLanguage = $node["Extract API Info (Android Client)"].json.preferredLanguage;

// Check multiple possible locations for captions
let captionTracks = null;

// Try primary location
if (playerData.captions && playerData.captions.playerCaptionsTracklistRenderer) {
  captionTracks = playerData.captions.playerCaptionsTracklistRenderer.captionTracks;
}

// Check if video is available and has captions
if (playerData.playabilityStatus) {
  if (playerData.playabilityStatus.status === 'UNPLAYABLE') {
    throw new Error(`Video is unplayable: ${playerData.playabilityStatus.reason || 'Unknown reason'}`);
  }
  if (playerData.playabilityStatus.status === 'ERROR') {
    throw new Error(`Video error: ${playerData.playabilityStatus.reason || 'Unknown error'}`);
  }
}

if (!captionTracks || captionTracks.length === 0) {
  // Provide helpful error message
  const videoTitle = playerData.videoDetails?.title || 'Unknown video';
  const videoId = $node["Extract API Info (Android Client)"].json.videoId;

  throw new Error(
    `No captions available for video: "${videoTitle}" (ID: ${videoId}). ` +
    `This video may not have subtitles/captions enabled, or they may be restricted. ` +
    `Try a different video or check if the video has CC available on YouTube.`
  );
}

// Process available tracks
const availableTracks = captionTracks.map(track => ({
  language: track.languageCode,
  name: track.name?.simpleText || track.name?.runs?.[0]?.text || track.languageCode,
  baseUrl: track.baseUrl,
  isTranslatable: track.isTranslatable || false,
  kind: track.kind || track.vssId?.includes('.a.') ? 'automatic' : 'standard',
  vssId: track.vssId
}));

// Find the preferred language track
let selectedTrack = availableTracks.find(track => 
  track.language === preferredLanguage || 
  track.language.startsWith(preferredLanguage + '-')
);

// Fallback to English if preferred not found
if (!selectedTrack && preferredLanguage !== 'en') {
  selectedTrack = availableTracks.find(track => 
    track.language === 'en' || 
    track.language.startsWith('en-')
  );
}

// Use first available if still not found
if (!selectedTrack) {
  selectedTrack = availableTracks[0];
}

// Add format parameter for better output
// selectedTrack.baseUrl += '&fmt=json3';

return [{
  json: {
    videoId: $node["Extract API Info (Android Client)"].json.videoId,
    videoTitle: playerData.videoDetails?.title || 'Unknown',
    videoAuthor: playerData.videoDetails?.author || 'Unknown',        // ADDED
    channelId: playerData.videoDetails?.channelId || '',              // ADDED
    viewCount: playerData.videoDetails?.viewCount || '0',             // ADDED (optional)
    videoDuration: playerData.videoDetails?.lengthSeconds || 0,
    selectedTrack: selectedTrack,
    availableTracks: availableTracks,
    totalTracks: availableTracks.length,
    trackType: selectedTrack.kind
  }
}];

// --- Helper function to clean up text ---
function cleanText(text) {
  return text
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

// --- Helper function to build the return object ---
function buildOutput(fullText, segments, format) {
  return [{
    json: {
      videoId: videoInfo.videoId,
      videoTitle: videoInfo.videoTitle || 'Unknown',
      videoAuthor: videoInfo.videoAuthor || 'Unknown',
      channelId: videoInfo.channelId || '',
      viewCount: videoInfo.viewCount || '0',
      language: videoInfo.selectedTrack.language,
      languageName: videoInfo.selectedTrack.name,
      transcriptType: videoInfo.trackType,
      segments,
      fullText,
      metadata: {
        videoUrl: `https://www.youtube.com/watch?v=${videoInfo.videoId}`,
        channelUrl: videoInfo.channelId ? `https://www.youtube.com/channel/${videoInfo.channelId}` : '',
        fetchedAt: new Date().toISOString(),
        format
      }
    }
  }];
}

// --- Main logic ---
const transcriptData = $input.first().json;
const videoInfo = $('Extract Caption Info (Enhanced)').first().json;

let fullText = '';
let segments = [];

// --- XML handling ---
const xmlData = transcriptData.data;

const paragraphRegex = /<p\s+t="(\d+)"(?:\s+d="(\d+)")?[^>]*>(.*?)<\/p>/gs;
let paragraphMatch;

while ((paragraphMatch = paragraphRegex.exec(xmlData)) !== null) {
  const startMs = parseInt(paragraphMatch[1], 10);
  const durationMs = paragraphMatch[2] ? parseInt(paragraphMatch[2], 10) : 0;
  const content = paragraphMatch[3];

  if (!content || content.trim() === '' || content.includes('a="1"')) continue;

  const sentenceMatches = [...content.matchAll(/<s(?:\s+[^>]*)?>([^<]*)<\/s>/g)];
  let paragraphText = sentenceMatches.map(s => s[1]).join('');
  paragraphText = cleanText(paragraphText);

  if (!paragraphText) continue;

  const start = startMs / 1000;
  const end = (startMs + durationMs) / 1000;

  segments.push({
    start,
    end,
    text: paragraphText
  });

  fullText += paragraphText + ' ';
}

fullText = cleanText(fullText);
if (!fullText) throw new Error('No transcript text could be extracted from the XML data');

return buildOutput(fullText, segments, 'XML');

// Get the transcript
const transcript = $('Process Transcript').first().json.fullText;

// Parameters
const maxChunkSize = 12000;
const overlapFraction = 0.15;
const overlapSize = Math.floor(maxChunkSize * overlapFraction);

// Arrays to hold results
const simpleChunks = [];
const overlappedChunks = [];

// --- SIMPLE CHUNKING ---
for (let start = 0; start < transcript.length; start += maxChunkSize) {
    const chunk = transcript.slice(start, start + maxChunkSize);
    simpleChunks.push(chunk);
}

// --- OVERLAPPED CHUNKING ---
for (let start = 0; start < transcript.length; start += (maxChunkSize - overlapSize)) {
    const chunk = transcript.slice(start, start + maxChunkSize);
    overlappedChunks.push(chunk);
}

// Combine into single array of objects for Airtable, adding order
const items = overlappedChunks.map((chunk, index) => {
    return {
        json: {
            order: index + 1,
            transcriptChunk: simpleChunks[index] || '', // optional fallback
            transcriptOverlappedChunk: chunk
        }
    };
});

return items;

// Get the segments
const segments = $('Process Transcript').first().json.segments;

// Parameters (700s window)
const maxWindowSize = 700; // seconds
const overlapFraction = 0.15;
const overlapSize = maxWindowSize * overlapFraction;
const stepSize = maxWindowSize - overlapSize;

// Arrays to hold results
const simpleChunks = [];
const overlappedSegmentChunks = [];

// Helper: get segments inside a time window
function getWindowSegments(startTime, endTime) {
    return segments.filter(
        s => s.start < endTime && s.end > startTime
    );
}

// --- SIMPLE CHUNKING (NO OVERLAP) ---
for (
    let start = 0;
    start < segments[segments.length - 1].end;
    start += maxWindowSize
) {
    const end = start + maxWindowSize;

    const windowSegments = getWindowSegments(start, end);

    simpleChunks.push({
        start,
        end,
        segments: windowSegments
    });
}

// --- OVERLAPPED SEGMENT WINDOWS (MAIN SYSTEM) ---
for (
    let start = 0;
    start < segments[segments.length - 1].end;
    start += stepSize
) {
    const end = start + maxWindowSize;

    const windowSegments = getWindowSegments(start, end);

    if (windowSegments.length === 0) continue;

    overlappedSegmentChunks.push({
        start,
        end,
        segments: windowSegments
    });
}

// --- FINAL AIRTABLE OUTPUT ---
const items = overlappedSegmentChunks.map((chunk, index) => {
    return {
        json: {
            order: index + 1,
            segments: simpleChunks[index]?.segments || [],
            overlappedSegments: chunk.segments,
        }
    };
});

return items;

const items = $input.all();
const OVERLAP_PERCENT = 0.15;      // 15% of second chunk to remove
const CHUNKS_PER_COMBINE = 4;       // Number of chunks to combine per pair
const combinedChunks = [];

for (let i = 0; i < items.length; i += CHUNKS_PER_COMBINE) {
    let combined = items[i].json.fields['Overlapped Transcript'];

    // Combine up to next CHUNKS_PER_COMBINE - 1 chunks
    for (let j = 1; j < CHUNKS_PER_COMBINE && i + j < items.length; j++) {
        const nextChunk = items[i + j].json.fields['Overlapped Transcript'];
        const sliceIndex = Math.floor(nextChunk.length * OVERLAP_PERCENT);
        combined += nextChunk.slice(sliceIndex);
    }

    combinedChunks.push({ json: { transcript: combined } });
}

return combinedChunks;

const combined = {
  key_insights: [],
  strong_hooks: [],
  quotes: [],
  stories: [],
  themes: []
};

for (const item of $input.all()) {
  const raw = item.json.text;
  const cleaned = raw.replace(/^```json\s*|\s*```$/g, "").trim();
  const data = JSON.parse(cleaned);

  for (const key of Object.keys(combined)) {
    if (Array.isArray(data[key])) {
      combined[key].push(...data[key]);
    }
  }
}

return [
  {
    json: {
      combined
    }
  }
];

const items = $input.all();

return items.map(item => {
  const raw = item.json.text || item.json;

  // If it's a string, clean + parse it
  const parsed =
    typeof raw === 'string'
