const items = $input.all();

const CHUNKS_PER_COMBINE = 4;
const combinedChunks = [];

function parseSegments(raw) {
    if (!raw) return [];
    if (Array.isArray(raw)) return raw;

    try {
        return JSON.parse(raw);
    } catch {
        return [];
    }
}

function isSameSegment(a, b) {
    return (
        a &&
        b &&
        a.start === b.start &&
        a.end === b.end &&
        a.text === b.text
    );
}

// Finds how many leading segments of `incoming` overlap with end of `base`
function findOverlapLength(base, incoming, maxCheck = 15) {
    const max = Math.min(base.length, incoming.length, maxCheck);

    for (let len = max; len > 0; len--) {
        let match = true;

        for (let i = 0; i < len; i++) {
            const a = base[base.length - len + i];
            const b = incoming[i];

            if (!isSameSegment(a, b)) {
                match = false;
                break;
            }
        }

        if (match) return len;
    }

    return 0;
}

function mergeWithEdgeDedup(base, incoming) {
    if (!base.length) return [...incoming];
    if (!incoming.length) return [...base];

    const overlapLen = findOverlapLength(base, incoming, 15);

    return base.concat(incoming.slice(overlapLen));
}

for (let i = 0; i < items.length; i += CHUNKS_PER_COMBINE) {

    let combinedSegments = [];

    for (let j = 0; j < CHUNKS_PER_COMBINE && i + j < items.length; j++) {
        const raw = items[i + j].json.fields["Overlapped Segment"];
        const segments = parseSegments(raw);

        combinedSegments = mergeWithEdgeDedup(combinedSegments, segments);
    }

    combinedChunks.push({
        json: {
            segments: combinedSegments
        }
    });
}

return combinedChunks;

const output = [];

for (const item of $input.all()) {
